    const form='<section class="fw-card"><div class="fw-section-head"><div><h2>ثبت چک جدید</h2><p>ثبت چک دریافتی یا پرداختی با گردش وضعیت</p></div></div><form data-form="cheque"><div class="fw-form-grid"><div class="fw-field"><label>نوع چک</label><select name="cheque_direction"><option value="received">چک دریافتی</option><option value="issued">چک پرداختی</option></select></div><div class="fw-field"><label>شخص</label><select name="contact_id" required><option value="">انتخاب شخص</option>'+people+'</select></div><div class="fw-field"><label>شماره چک</label><input name="cheque_number" required maxlength="80"></div><div class="fw-field"><label>شناسه صیادی</label><input name="sayad_id" inputmode="numeric" maxlength="16"></div><div class="fw-field"><label>بانک</label><input name="bank_name"></div><div class="fw-field"><label>شعبه</label><input name="branch_name"></div><div class="fw-field"><label>مبلغ ('+currencyLabel()+')</label><input name="amount" type="number" min="1" step="1" required></div><div class="fw-field"><label>تاریخ صدور</label><input name="issue_date" type="date" value="'+today()+'"></div><div class="fw-field"><label>تاریخ سررسید</label><input name="due_date" type="date" required></div><div class="fw-field"><label>صاحب حساب</label><input name="account_holder"></div><div class="fw-field"><label>صادرکننده</label><input name="drawer_name"></div><div class="fw-field"><label>در وجه</label><input name="payee_name"></div><div class="fw-field wide"><label>توضیحات</label><input name="note" maxlength="500"></div></div><button class="fw-btn" type="submit">ذخیره چک</button></form></section>';
    shell(form+'<section class="fw-card" style="margin-top:16px"><div class="fw-section-head"><div><h2>دفتر چک‌ها</h2><p>'+money(state.cheques.length)+' چک ثبت‌شده</p></div></div>'+table(rows,['شماره','نوع','شخص','سررسید','مبلغ','وضعیت','عملیات'],'چکی ثبت نشده است.')+'</section><section class="fw-card" style="margin-top:16px"><div class="fw-section-head"><div><h2>تاریخچه رویدادهای چک</h2><p>واگذاری، تسویه، برگشت و لغو</p></div></div>'+table(eventRows,['شماره چک','تاریخ رویداد','عملیات','مبلغ','شرح'],'رویدادی ثبت نشده است.')+'</section><section class="fw-card" style="margin-top:16px"><div class="fw-section-head"><div><h2>چک‌های قدیمی اپلیکیشن</h2><p>برای حفظ سوابق، این موارد فقط‌خواندنی هستند.</p></div></div>'+table(legacyCheques,['شماره','نوع','شخص','سررسید','مبلغ','وضعیت','منبع'],'چک قدیمی ثبت نشده است.')+'</section>','مدیریت چک‌ها','ثبت و پیگیری چک‌های دریافتی و پرداختی');
